package auth

import (
	"net"
	"testing"
	"time"
)

// mockAddr implements net.Addr for testing
type mockAddr struct {
	network string
	addr    string
}

func (m mockAddr) Network() string { return m.network }
func (m mockAddr) String() string  { return m.addr }

func TestExtractIP(t *testing.T) {
	tests := []struct {
		name     string
		addr     net.Addr
		expected string
	}{
		{
			name:     "IPv4 with port",
			addr:     mockAddr{"tcp", "192.168.1.1:5432"},
			expected: "192.168.1.1",
		},
		{
			name:     "IPv6 with port",
			addr:     mockAddr{"tcp", "[::1]:5432"},
			expected: "::1",
		},
		{
			name:     "localhost with port",
			addr:     mockAddr{"tcp", "127.0.0.1:12345"},
			expected: "127.0.0.1",
		},
		{
			name:     "no port (returns as-is)",
			addr:     mockAddr{"tcp", "192.168.1.1"},
			expected: "192.168.1.1",
		},
		{
			name:     "nil addr",
			addr:     nil,
			expected: "",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := extractIP(tt.addr)
			if result != tt.expected {
				t.Errorf("extractIP(%v) = %q, want %q", tt.addr, result, tt.expected)
			}
		})
	}
}

func TestRateLimiter_BasicOperations(t *testing.T) {
	cfg := RateLimitConfig{
		MaxFailedAttempts:   3,
		FailedAttemptWindow: 1 * time.Minute,
		BanDuration:         5 * time.Minute,
		MaxConnectionsPerIP: 5,
	}
	rl := NewRateLimiter(cfg)

	addr := mockAddr{"tcp", "192.168.1.100:5432"}

	t.Run("initial connection allowed", func(t *testing.T) {
		msg := rl.CheckConnection(addr)
		if msg != "" {
			t.Errorf("CheckConnection() should allow initial connection, got: %s", msg)
		}
	})

	t.Run("register connection", func(t *testing.T) {
		ok := rl.RegisterConnection(addr)
		if !ok {
			t.Error("RegisterConnection() should succeed")
		}
	})

	t.Run("unregister connection", func(t *testing.T) {
		rl.UnregisterConnection(addr)
		// Should not panic, connection count should be 0
	})

	t.Run("unregister non-existent connection", func(t *testing.T) {
		newAddr := mockAddr{"tcp", "10.0.0.1:5432"}
		rl.UnregisterConnection(newAddr) // Should not panic
	})
}

func TestRateLimiter_ConnectionLimit(t *testing.T) {
	cfg := RateLimitConfig{
		MaxFailedAttempts:   5,
		FailedAttemptWindow: 1 * time.Minute,
		BanDuration:         5 * time.Minute,
		MaxConnectionsPerIP: 3,
	}
	rl := NewRateLimiter(cfg)

	addr := mockAddr{"tcp", "192.168.1.100:5432"}

	// Register max connections
	for i := 0; i < 3; i++ {
		ok := rl.RegisterConnection(addr)
		if !ok {
			t.Errorf("RegisterConnection() %d should succeed", i+1)
		}
	}

	t.Run("exceeds connection limit", func(t *testing.T) {
		ok := rl.RegisterConnection(addr)
		if ok {
			t.Error("RegisterConnection() should fail when at limit")
		}

		msg := rl.CheckConnection(addr)
		if msg == "" {
			t.Error("CheckConnection() should return error when at limit")
		}
		if msg != "too many connections from your IP address" {
			t.Errorf("unexpected error message: %s", msg)
		}
	})

	t.Run("allows connection after unregister", func(t *testing.T) {
		rl.UnregisterConnection(addr)
		ok := rl.RegisterConnection(addr)
		if !ok {
			t.Error("RegisterConnection() should succeed after unregister")
		}
	})
}

func TestRateLimiter_FailedAuth(t *testing.T) {
	cfg := RateLimitConfig{
		MaxFailedAttempts:   3,
		FailedAttemptWindow: 1 * time.Minute,
		BanDuration:         100 * time.Millisecond, // Short for testing
		MaxConnectionsPerIP: 100,
	}
	rl := NewRateLimiter(cfg)

	addr := mockAddr{"tcp", "192.168.1.100:5432"}

	t.Run("not banned after fewer than max attempts", func(t *testing.T) {
		// 2 failed attempts (below threshold of 3)
		rl.RecordFailedAuth(addr)
		rl.RecordFailedAuth(addr)

		if rl.IsBanned(addr) {
			t.Error("Should not be banned after 2 failed attempts (max is 3)")
		}
	})

	t.Run("banned after max attempts", func(t *testing.T) {
		// 3rd failed attempt (reaches threshold)
		banned := rl.RecordFailedAuth(addr)
		if !banned {
			t.Error("RecordFailedAuth() should return true when ban threshold reached")
		}

		if !rl.IsBanned(addr) {
			t.Error("IsBanned() should return true after max failed attempts")
		}

		// Check that connection is rejected
		msg := rl.CheckConnection(addr)
		if msg == "" {
			t.Error("CheckConnection() should return error when banned")
		}
	})

	t.Run("ban expires", func(t *testing.T) {
		// Wait for ban to expire
		time.Sleep(150 * time.Millisecond)

		if rl.IsBanned(addr) {
			t.Error("IsBanned() should return false after ban expires")
		}

		msg := rl.CheckConnection(addr)
		if msg != "" {
			t.Errorf("CheckConnection() should allow connection after ban expires, got: %s", msg)
		}
	})
}

func TestRateLimiter_SuccessfulAuth(t *testing.T) {
	cfg := RateLimitConfig{
		MaxFailedAttempts:   3,
		FailedAttemptWindow: 1 * time.Minute,
		BanDuration:         5 * time.Minute,
		MaxConnectionsPerIP: 100,
	}
	rl := NewRateLimiter(cfg)

	addr := mockAddr{"tcp", "192.168.1.100:5432"}

	// Record some failed attempts (but not enough to ban)
	rl.RecordFailedAuth(addr)
	rl.RecordFailedAuth(addr)

	// Successful auth should clear failed attempts
	rl.RecordSuccessfulAuth(addr)

	// Now 3 more failed attempts should be needed to ban
	rl.RecordFailedAuth(addr)
	rl.RecordFailedAuth(addr)
	if rl.IsBanned(addr) {
		t.Error("Should not be banned - successful auth should have reset counter")
	}

	// 3rd attempt after reset should trigger ban
	banned := rl.RecordFailedAuth(addr)
	if !banned {
		t.Error("Should be banned after 3 failed attempts following reset")
	}
}

func TestRateLimiter_DifferentIPs(t *testing.T) {
	cfg := RateLimitConfig{
		MaxFailedAttempts:   2,
		FailedAttemptWindow: 1 * time.Minute,
		BanDuration:         5 * time.Minute,
		MaxConnectionsPerIP: 100,
	}
	rl := NewRateLimiter(cfg)

	addr1 := mockAddr{"tcp", "192.168.1.1:5432"}
	addr2 := mockAddr{"tcp", "192.168.1.2:5432"}

	// Ban addr1
	rl.RecordFailedAuth(addr1)
	rl.RecordFailedAuth(addr1)

	if !rl.IsBanned(addr1) {
		t.Error("addr1 should be banned")
	}

	// addr2 should not be affected
	if rl.IsBanned(addr2) {
		t.Error("addr2 should not be banned")
	}

	msg := rl.CheckConnection(addr2)
	if msg != "" {
		t.Errorf("addr2 should be allowed, got: %s", msg)
	}
}

func TestRateLimiter_NilAddr(t *testing.T) {
	cfg := DefaultRateLimitConfig()
	rl := NewRateLimiter(cfg)

	// All operations with nil addr should succeed/not panic
	t.Run("CheckConnection nil", func(t *testing.T) {
		msg := rl.CheckConnection(nil)
		if msg != "" {
			t.Errorf("CheckConnection(nil) should return empty, got: %s", msg)
		}
	})

	t.Run("RegisterConnection nil", func(t *testing.T) {
		ok := rl.RegisterConnection(nil)
		if !ok {
			t.Error("RegisterConnection(nil) should return true")
		}
	})

	t.Run("UnregisterConnection nil", func(t *testing.T) {
		rl.UnregisterConnection(nil) // Should not panic
	})

	t.Run("RecordFailedAuth nil", func(t *testing.T) {
		banned := rl.RecordFailedAuth(nil)
		if banned {
			t.Error("RecordFailedAuth(nil) should return false")
		}
	})

	t.Run("RecordSuccessfulAuth nil", func(t *testing.T) {
		rl.RecordSuccessfulAuth(nil) // Should not panic
	})

	t.Run("IsBanned nil", func(t *testing.T) {
		if rl.IsBanned(nil) {
			t.Error("IsBanned(nil) should return false")
		}
	})
}

func TestRateLimiter_UnlimitedConnections(t *testing.T) {
	cfg := RateLimitConfig{
		MaxFailedAttempts:   5,
		FailedAttemptWindow: 1 * time.Minute,
		BanDuration:         5 * time.Minute,
		MaxConnectionsPerIP: 0, // Unlimited
	}
	rl := NewRateLimiter(cfg)

	addr := mockAddr{"tcp", "192.168.1.100:5432"}

	// Should be able to register many connections
	for i := 0; i < 1000; i++ {
		ok := rl.RegisterConnection(addr)
		if !ok {
			t.Errorf("RegisterConnection() %d should succeed with unlimited config", i+1)
			break
		}
	}
}

func TestRateLimiter_GlobalConnectionLimit(t *testing.T) {
	cfg := RateLimitConfig{
		MaxFailedAttempts:   5,
		FailedAttemptWindow: 1 * time.Minute,
		BanDuration:         5 * time.Minute,
		MaxConnectionsPerIP: 100,
		MaxConnections:      2,
	}
	rl := NewRateLimiter(cfg)

	addr1 := mockAddr{"tcp", "192.168.1.1:5432"}
	addr2 := mockAddr{"tcp", "192.168.1.2:5432"}
	addr3 := mockAddr{"tcp", "192.168.1.3:5432"}

	// Register 2 connections (at limit)
	if !rl.RegisterConnection(addr1) {
		t.Fatal("RegisterConnection(addr1) should succeed")
	}
	if !rl.RegisterConnection(addr2) {
		t.Fatal("RegisterConnection(addr2) should succeed")
	}

	t.Run("exceeds global limit", func(t *testing.T) {
		if rl.RegisterConnection(addr3) {
			t.Error("RegisterConnection(addr3) should fail when at global limit")
		}

		msg := rl.CheckConnection(addr3)
		if msg != "too many concurrent connections" {
			t.Errorf("unexpected error message: %s", msg)
		}
	})

	t.Run("allows connection after unregister", func(t *testing.T) {
		rl.UnregisterConnection(addr1)
		if !rl.RegisterConnection(addr3) {
			t.Error("RegisterConnection(addr3) should succeed after unregistering addr1")
		}
	})
}

func TestDefaultRateLimitConfig(t *testing.T) {
	cfg := DefaultRateLimitConfig()

	if cfg.MaxFailedAttempts != 5 {
		t.Errorf("MaxFailedAttempts = %d, want 5", cfg.MaxFailedAttempts)
	}
	if cfg.FailedAttemptWindow != 5*time.Minute {
		t.Errorf("FailedAttemptWindow = %v, want 5m", cfg.FailedAttemptWindow)
	}
	if cfg.BanDuration != 15*time.Minute {
		t.Errorf("BanDuration = %v, want 15m", cfg.BanDuration)
	}
	if cfg.MaxConnectionsPerIP != 500 {
		t.Errorf("MaxConnectionsPerIP = %d, want 500", cfg.MaxConnectionsPerIP)
	}
	if cfg.MaxConnections != 1024 {
		t.Errorf("MaxConnections = %d, want 1024", cfg.MaxConnections)
	}
}

package controlplane

import (
	"bytes"
	"compress/gzip"
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"net/http/httptest"
	"sync"
	"testing"
	"time"

	"github.com/gin-gonic/gin"

	"github.com/posthog/duckgres/controlplane/configstore"
)

// fakeBillingStore implements billingUsageStore + computeGCStore in memory.
type fakeBillingStore struct {
	mu          sync.Mutex
	cursor      time.Time
	hasAck      bool
	rows        []configstore.ComputeUsageRow
	storageRows []configstore.StorageUsageRow
	aggLow      time.Time
	aggHigh     time.Time
	stAggLow    time.Time
	stAggHigh   time.Time
	ackedTo     time.Time
	deleted     int64
	gcCutoff    time.Time
	gcDrop      int64
	failWith    error
}

func (f *fakeBillingStore) AggregateComputeUsage(low, high time.Time) ([]configstore.ComputeUsageRow, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.failWith != nil {
		return nil, f.failWith
	}
	f.aggLow, f.aggHigh = low, high
	return f.rows, nil
}

func (f *fakeBillingStore) AggregateStorageUsage(low, high time.Time) ([]configstore.StorageUsageRow, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.failWith != nil {
		return nil, f.failWith
	}
	f.stAggLow, f.stAggHigh = low, high
	return f.storageRows, nil
}

func (f *fakeBillingStore) ComputeBillingCursor() (time.Time, bool, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.failWith != nil {
		return time.Time{}, false, f.failWith
	}
	return f.cursor, f.hasAck, nil
}

func (f *fakeBillingStore) AckComputeUsage(high time.Time) (int64, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.failWith != nil {
		return 0, f.failWith
	}
	if high.After(f.cursor) {
		f.cursor, f.hasAck = high, true
	}
	f.ackedTo = high
	return f.deleted, nil
}

func (f *fakeBillingStore) GCComputeUsage(olderThan time.Time) (int64, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.failWith != nil {
		return 0, f.failWith
	}
	f.gcCutoff = olderThan
	return f.gcDrop, nil
}

func newBillingTestRouter(store *fakeBillingStore, now time.Time) *gin.Engine {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	h := &billingAPIHandler{store: store, now: func() time.Time { return now }}
	grp := r.Group("/api/v1")
	grp.GET("/billing/usage", h.getUsage)
	grp.POST("/billing/ack", h.postAck)
	return r
}

// TestRegisterBillingAPIGatesBothRoutes exercises the real registration used
// by multitenant.go: both routes are mounted and BOTH pass through the
// admin-gating middleware (a viewer/billing-secret mixup must never reach the
// ack mutation or raw usage).
func TestRegisterBillingAPIGatesBothRoutes(t *testing.T) {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	gateHits := 0
	deny := func(c *gin.Context) {
		gateHits++
		c.AbortWithStatus(http.StatusForbidden)
	}
	registerBillingAPI(r.Group("/api/v1"), &fakeBillingStore{}, deny)

	for _, req := range []*http.Request{
		httptest.NewRequest(http.MethodGet, "/api/v1/billing/usage", nil),
		httptest.NewRequest(http.MethodPost, "/api/v1/billing/ack", bytes.NewReader([]byte(`{"watermark_high":"2026-07-01T12:39:00Z"}`))),
	} {
		rec := httptest.NewRecorder()
		r.ServeHTTP(rec, req)
		if rec.Code != http.StatusForbidden {
			t.Fatalf("%s %s = %d, want 403 from the admin gate", req.Method, req.URL.Path, rec.Code)
		}
	}
	if gateHits != 2 {
		t.Fatalf("admin gate ran %d times, want 2 (every billing route must be gated)", gateHits)
	}
}

type usageResponse struct {
	WatermarkLow  time.Time                     `json:"watermark_low"`
	WatermarkHigh time.Time                     `json:"watermark_high"`
	Usage         []configstore.ComputeUsageRow `json:"usage"`
	Storage       []configstore.StorageUsageRow `json:"storage"`
}

func TestBillingUsageWindowAndRows(t *testing.T) {
	now := time.Date(2026, 7, 1, 12, 40, 47, 0, time.UTC)
	cursor := time.Date(2026, 7, 1, 12, 30, 0, 0, time.UTC)
	store := &fakeBillingStore{
		cursor: cursor, hasAck: true,
		rows: []configstore.ComputeUsageRow{{
			Date: "2026-07-01", OrgID: "org_abc", TeamID: 12345, QuerySource: "standard",
			CPU: "8", MemGiB: "16", CPUSeconds: 4800, MemorySeconds: 9600,
		}},
		storageRows: []configstore.StorageUsageRow{{
			Date: "2026-07-01", OrgID: "org_abc", TeamID: 12345, GiBSeconds: "18000000.5",
		}},
	}
	router := newBillingTestRouter(store, now)

	rec := httptest.NewRecorder()
	router.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/api/v1/billing/usage", nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d: %s", rec.Code, rec.Body.String())
	}
	var resp usageResponse
	if err := json.Unmarshal(rec.Body.Bytes(), &resp); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if !resp.WatermarkLow.Equal(cursor) {
		t.Fatalf("watermark_low = %v, want cursor %v", resp.WatermarkLow, cursor)
	}
	// Latest closed bucket at 12:40:47 with 60s width + 30s grace:
	// 12:40:47 − 90s = 12:39:17 → truncated to 12:39:00.
	wantHigh := time.Date(2026, 7, 1, 12, 39, 0, 0, time.UTC)
	if !resp.WatermarkHigh.Equal(wantHigh) {
		t.Fatalf("watermark_high = %v, want %v", resp.WatermarkHigh, wantHigh)
	}
	// The aggregate window must be exactly (cursor, high].
	if !store.aggLow.Equal(cursor) || !store.aggHigh.Equal(wantHigh) {
		t.Fatalf("aggregate window = (%v, %v], want (%v, %v]", store.aggLow, store.aggHigh, cursor, wantHigh)
	}
	if len(resp.Usage) != 1 || resp.Usage[0].OrgID != "org_abc" || resp.Usage[0].CPUSeconds != 4800 {
		t.Fatalf("usage = %+v", resp.Usage)
	}
	// The exact-decimal sizes must serialize as unquoted JSON numbers.
	if !bytes.Contains(rec.Body.Bytes(), []byte(`"cpu":8`)) || !bytes.Contains(rec.Body.Bytes(), []byte(`"mem_gib":16`)) {
		t.Fatalf("cpu/mem_gib not serialized as JSON numbers: %s", rec.Body.String())
	}
	// Storage rides the same window: same aggregate bounds, rows served, and
	// gib_seconds as an unquoted JSON number.
	if !store.stAggLow.Equal(cursor) || !store.stAggHigh.Equal(wantHigh) {
		t.Fatalf("storage aggregate window = (%v, %v], want (%v, %v]", store.stAggLow, store.stAggHigh, cursor, wantHigh)
	}
	if len(resp.Storage) != 1 || resp.Storage[0].OrgID != "org_abc" || resp.Storage[0].TeamID != 12345 {
		t.Fatalf("storage = %+v", resp.Storage)
	}
	if !bytes.Contains(rec.Body.Bytes(), []byte(`"gib_seconds":18000000.5`)) {
		t.Fatalf("gib_seconds not serialized as a JSON number: %s", rec.Body.String())
	}
}

func TestBillingUsageNeverAckedServesEverything(t *testing.T) {
	// No cursor row yet → the window starts at the zero time (serves all
	// buffered history).
	now := time.Date(2026, 7, 1, 12, 40, 47, 0, time.UTC)
	store := &fakeBillingStore{}
	router := newBillingTestRouter(store, now)

	rec := httptest.NewRecorder()
	router.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/api/v1/billing/usage", nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d: %s", rec.Code, rec.Body.String())
	}
	if !store.aggLow.IsZero() {
		t.Fatalf("window low = %v, want zero time when never acked", store.aggLow)
	}
}

func TestBillingUsageEmptyWindowWhenCursorCurrent(t *testing.T) {
	// Cursor already at the latest closed bucket → nothing to serve; the
	// response must be a valid empty window with high == low, not an error.
	now := time.Date(2026, 7, 1, 12, 40, 47, 0, time.UTC)
	cursor := time.Date(2026, 7, 1, 12, 39, 0, 0, time.UTC)
	store := &fakeBillingStore{cursor: cursor, hasAck: true}
	router := newBillingTestRouter(store, now)

	rec := httptest.NewRecorder()
	router.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/api/v1/billing/usage", nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d: %s", rec.Code, rec.Body.String())
	}
	var resp usageResponse
	if err := json.Unmarshal(rec.Body.Bytes(), &resp); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if !resp.WatermarkHigh.Equal(resp.WatermarkLow) || !resp.WatermarkLow.Equal(cursor) {
		t.Fatalf("want empty window at cursor, got (%v, %v]", resp.WatermarkLow, resp.WatermarkHigh)
	}
	if len(resp.Usage) != 0 || len(resp.Storage) != 0 {
		t.Fatalf("usage/storage = %+v / %+v, want empty", resp.Usage, resp.Storage)
	}
	if !store.aggLow.IsZero() || !store.aggHigh.IsZero() || !store.stAggLow.IsZero() {
		t.Fatal("aggregates must not run for an empty window")
	}
}

func TestBillingAckAdvancesAndIsBounded(t *testing.T) {
	now := time.Date(2026, 7, 1, 12, 40, 47, 0, time.UTC)
	store := &fakeBillingStore{deleted: 7}
	router := newBillingTestRouter(store, now)

	// A valid ack (≤ latest closed bucket) advances and reports deletions.
	body := []byte(`{"watermark_high":"2026-07-01T12:39:00Z"}`)
	rec := httptest.NewRecorder()
	router.ServeHTTP(rec, httptest.NewRequest(http.MethodPost, "/api/v1/billing/ack", bytes.NewReader(body)))
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d: %s", rec.Code, rec.Body.String())
	}
	if want := time.Date(2026, 7, 1, 12, 39, 0, 0, time.UTC); !store.ackedTo.Equal(want) {
		t.Fatalf("acked = %v, want %v", store.ackedTo, want)
	}
	var resp struct {
		Deleted int64 `json:"deleted"`
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &resp); err != nil || resp.Deleted != 7 {
		t.Fatalf("deleted = %d (err=%v), want 7", resp.Deleted, err)
	}

	// An ack beyond the latest closed bucket must be rejected — it could
	// delete buckets that were never served.
	store.ackedTo = time.Time{}
	body = []byte(`{"watermark_high":"2026-07-01T12:40:00Z"}`)
	rec = httptest.NewRecorder()
	router.ServeHTTP(rec, httptest.NewRequest(http.MethodPost, "/api/v1/billing/ack", bytes.NewReader(body)))
	if rec.Code != http.StatusBadRequest {
		t.Fatalf("future ack status = %d, want 400: %s", rec.Code, rec.Body.String())
	}
	if !store.ackedTo.IsZero() {
		t.Fatal("future ack must not reach the store")
	}

	// Garbage body → 400.
	rec = httptest.NewRecorder()
	router.ServeHTTP(rec, httptest.NewRequest(http.MethodPost, "/api/v1/billing/ack", bytes.NewReader([]byte(`{}`))))
	if rec.Code != http.StatusBadRequest {
		t.Fatalf("empty ack status = %d, want 400: %s", rec.Code, rec.Body.String())
	}
}

func TestBillingStoreErrorsSurfaceAs500(t *testing.T) {
	now := time.Date(2026, 7, 1, 12, 40, 47, 0, time.UTC)
	store := &fakeBillingStore{failWith: errors.New("db down")}
	router := newBillingTestRouter(store, now)

	rec := httptest.NewRecorder()
	router.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/api/v1/billing/usage", nil))
	if rec.Code != http.StatusInternalServerError {
		t.Fatalf("usage status = %d, want 500", rec.Code)
	}
	rec = httptest.NewRecorder()
	router.ServeHTTP(rec, httptest.NewRequest(http.MethodPost, "/api/v1/billing/ack", bytes.NewReader([]byte(`{"watermark_high":"2026-07-01T12:39:00Z"}`))))
	if rec.Code != http.StatusInternalServerError {
		t.Fatalf("ack status = %d, want 500", rec.Code)
	}
}

func TestComputeUsageGCRunsAndStops(t *testing.T) {
	store := &fakeBillingStore{gcDrop: 3}
	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan struct{})
	go func() { runComputeUsageGC(ctx, store); close(done) }()
	// The first tick runs immediately; wait for it, then cancel.
	deadline := time.After(2 * time.Second)
	for {
		store.mu.Lock()
		got := store.gcCutoff
		store.mu.Unlock()
		if !got.IsZero() {
			if d := time.Since(got); d < computeUsageRetention-time.Minute || d > computeUsageRetention+time.Minute {
				t.Fatalf("gc cutoff %v not ~retention (30d) ago", got)
			}
			break
		}
		select {
		case <-deadline:
			t.Fatal("gc first tick never ran")
		default:
			time.Sleep(10 * time.Millisecond)
		}
	}
	cancel()
	select {
	case <-done:
	case <-time.After(2 * time.Second):
		t.Fatal("gc loop did not stop on cancel")
	}
}

